-- Highlights and categories for packages (shown on tour pages and as Packages filters).

alter table public.tours
  add column highlights text[] not null default '{}',
  add column categories text[] not null default '{}';

-- Fill in the six packages migrated from WordPress (written from their own itineraries).
update public.tours set highlights = array['18 holes at Royal Colombo Golf Club, the oldest golf club in Sri Lanka', 'Scenic, challenging Victoria Golf & Country Resort, with an optional second round', 'Nuwara Eliya Golf Club, one of Asia''s oldest and most picturesque courses', 'Tea country drive with a tea factory visit', 'Colonial-style stay in Nuwara Eliya, "Little England"']::text[], categories = array['Golf', 'Nature']::text[] where slug = 'luxury-golf-escape';
update public.tours set highlights = array['Full-day tour of working gem pits in Ratnapura, the City of Gems', 'Learn traditional pit mining, gem washing and evaluation', 'Yala National Park and a Bundala safari for migratory birds', 'Galle''s UNESCO-listed Dutch Fort', 'Beach time in Bentota and a Colombo city tour']::text[], categories = array['Gems', 'Wildlife', 'Beach']::text[] where slug = 'discover-gems';
update public.tours set highlights = array['Baby elephants at Pinnawala Elephant Orphanage', 'Temple of the Sacred Tooth Relic and Peradeniya Botanical Garden', 'Hike to World''s End and Baker''s Falls in Horton Plains', 'Jeep safari in Yala, home to leopards, elephants and sloth bears', 'Birdwatching in Bundala and the Galle Dutch Fort']::text[], categories = array['Wildlife', 'Culture', 'Nature', 'Beach']::text[] where slug = 'nature-culture-tour';
update public.tours set highlights = array['Ancient capitals Anuradhapura and Polonnaruwa', 'Sigiriya Rock Fortress and Dambulla Cave Temple', 'Temple of the Sacred Tooth Relic, Pinnawala elephants and a cultural dance show', 'Tea country, waterfalls and the Ella Gap', 'Jeep safari in Yala National Park', 'Stilt fishermen, Galle Fort and two beach days in Bentota']::text[], categories = array['Culture', 'Wildlife', 'Nature', 'Beach']::text[] where slug = 'exotic-sri-lanka-tour';
update public.tours set highlights = array['Garland welcome at the airport', 'Temple of the Sacred Tooth Relic in Kandy', 'Tea plantations, a tea factory and waterfalls in Nuwara Eliya', 'Royal Botanical Gardens in Peradeniya', 'Feed baby elephants at Pinnawala', 'Spice garden, batik factory and Colombo shopping']::text[], categories = array['Romantic', 'Culture', 'Nature']::text[] where slug = 'romantic-getaway';
update public.tours set highlights = array['Baby elephants at Pinnawala Elephant Orphanage', 'Peradeniya Botanical Gardens and its Orchid House', 'Dambulla Cave Temple, a UNESCO World Heritage Site', 'The medieval capital of Polonnaruwa', 'Sri Maha Bodhi and the sacred sites of Anuradhapura', 'Colombo sightseeing and shopping']::text[], categories = array['Culture']::text[] where slug = 'explore-paradise';
